using System.Text;using System.Security.Cryptography;using QIQI.EProjectFile;using QIQI.EProjectFile.Sections;using QIQI.EProjectFile.Context;
Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);
static byte[] Ksa(byte[] key, byte[]? initial=null){var s=initial?.ToArray()??Enumerable.Range(0,256).Select(i=>(byte)i).ToArray();int j=0;if(key.Length>0){for(int i=0;i<256;i++){j=(j+s[i]+key[i%key.Length])%256;(s[i],s[j])=(s[j],s[i]);}}return s;}
static void Rc4(byte[] data, byte[] key, int skip=0){var s=Ksa(key);int i=0,j=0;byte Step(byte x){i=(i+1)&255;j=(j+s[i])&255;(s[i],s[j])=(s[j],s[i]);return (byte)(x^s[(s[i]+s[j])&255]);}for(int n=0;n<skip;n++)Step(0);for(int n=0;n<data.Length;n++)data[n]=Step(data[n]);}
static byte[] DecryptStd(byte[] file,string pass){if(file.Length<8||BitConverter.ToInt32(file,0)!=0x454c5457||BitConverter.ToInt32(file,4)!=1)return file;var pwd=Encoding.GetEncoding("gbk").GetBytes(pass);var secret=MD5.HashData(pwd).Reverse().SelectMany(x=>Encoding.ASCII.GetBytes(x.ToString("x2"))).ToArray();var iv=Ksa(pwd);var ktS=iv;int ktI=0,ktJ=0,idx=0,rem=8;var stream=new byte[file.Length];Buffer.BlockCopy(file,0,stream,0,file.Length);var output=new byte[file.Length];while(idx*4096<stream.Length){int pos=idx*4096,n=Math.Min(4096,stream.Length-pos);var ks=new byte[4];for(int z=0;z<4;z++){ktI=(ktI+1)&255;ktJ=(ktJ+ktS[ktI])&255;(ktS[ktI],ktS[ktJ])=(ktS[ktJ],ktS[ktI]);ks[z]=ktS[(ktS[ktI]+ktS[ktJ])&255];}int prefix=BitConverter.ToInt32(ks,0);var key=new byte[40];Buffer.BlockCopy(ks,0,key,0,4);Buffer.BlockCopy(secret,0,key,4,32);Buffer.BlockCopy(BitConverter.GetBytes(idx^prefix),0,key,36,4);var chunk=new byte[n];Buffer.BlockCopy(stream,pos,chunk,0,n);Rc4(chunk,key,36);int untouched=Math.Min(rem,n);Buffer.BlockCopy(stream,pos,output,pos,untouched);Buffer.BlockCopy(chunk,untouched,output,pos+untouched,n-untouched);rem=Math.Max(0,rem-n);idx++;}var plain=new byte[output.Length-40];Buffer.BlockCopy(output,40,plain,0,plain.Length);return plain;}
if(args.Length<2){Console.Error.WriteLine("usage: eproject_dump <password> <file> [out]");return 2;}var pass=args[0];var input=args[1];var output=args.Length>2?args[2]:input+".txt";var bytes=DecryptStd(File.ReadAllBytes(input),pass);using var ms=new MemoryStream(bytes);using var rd=new ProjectFileReader(ms,null);var raws=new List<RawSectionInfo>();while(!rd.IsFinish)raws.Add(rd.ReadSection());var sb=new StringBuilder();sb.AppendLine($"FILE={input}");sb.AppendLine($"SECTIONS={raws.Count}");foreach(var s in raws)sb.AppendLine($"SECTION 0x{s.Key:X8} NAME={s.Name} OPTIONAL={s.IsOptional} DATA={s.Data.Length}");var cr=raws.FirstOrDefault(x=>x.Key==0x03007319);if(cr.Data!=null){try{var code=CodeSection.Key.Parse(new BlockParserContext(cr.Data,Encoding.GetEncoding("gbk"),false));sb.AppendLine($"CODE METHODS={code.Methods?.Count??0} GLOBALS={code.GlobalVariables?.Count??0} CLASSES={code.Classes?.Count??0} DLLS={code.DllDeclares?.Count??0} LIBS={code.Libraries?.Length??0}");using var tw=new StringWriter(sb);code.ToTextCode(new IdToNameMap(code,null),tw,0,true,true);}catch(Exception ex){sb.AppendLine("CODE_PARSE_ERROR "+ex);}}File.WriteAllText(output,sb.ToString(),new UTF8Encoding(false));Console.WriteLine(output);return 0;


